    fn call_route(&self, match_: matchit::Match<&RouteId>, mut req: Request<B>) -> RouterFuture<B> {
        let id = *match_.value;
        self.capture_route_id(&mut req, id);

        if let Some(matched_path) = self.node.route_id_to_path.get(&id).cloned() {
            let combined = self.combine_matched_path(req.extensions().get::<MatchedPath>(), matched_path);
            req.extensions_mut().insert(MatchedPath(combined));
        } else {
            #[cfg(debug_assertions)]
            panic!("should always have a matched path for a route id");
        }

        let params = self.collect_match_params(&match_);

        self.store_url_params(&mut req, params);

        let mut route = self
            .routes
            .get(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
            .clone();

        let future = match &mut route {
            Endpoint::MethodRouter(inner) => inner.call(req),
            Endpoint::Route(inner) => inner.call(req),
        };
        RouterFuture::from_future(future)
    }

    fn panic_on_matchit_error(&self, err: matchit::InsertError) {
        if self.nested_at_root {
            panic!(
                "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                err,
            );
        } else {
            panic!("Invalid route: {}", err);
        }
    }
}

impl<B> Service<Request<B>> for Router<B>
where
    B: Send + 'static,
{
    type Response = Response;
    type Error = Infallible;
    type Future = RouterFuture<B>;

    #[inline]
    fn poll_ready(&mut self, _: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        self.maybe_store_original_uri(&mut req);

        let path = req.uri().path().to_owned();

        match self.node.at(&path) {
            Ok(match_) => self.call_route(match_, req),
            Err(err) => {
                if err.tsr() {
                    let target = self.trailing_slash_target(&path);
                    let redirect_to = self.rewrite_uri_path(req.uri(), &target);
                    let res = self.moved_permanently_response(redirect_to);
                    RouterFuture::from_response(res)
                } else {
                    match &self.fallback {
                        Fallback::Default(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                        Fallback::Custom(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                    }
                }
            }
        }
    }
}


impl<B> Router<B> {
    fn remember_nested_prefix(&mut self, prefix: &str) {
        if prefix.is_empty() {
            return;
        }
        if self
            .nest_policy
            .known_prefixes
            .iter()
            .any(|known| known.as_ref() == prefix)
        {
            return;
        }
        self.nest_policy.known_prefixes.push(Arc::from(prefix));
    }

    fn resolve_known_prefix<'a>(&'a self, prefix: &'a str) -> &'a str {
        if let Some(known) = self
            .nest_policy
            .known_prefixes
            .iter()
            .find(|known| known.as_ref() == prefix)
        {
            known.as_ref()
        } else {
            prefix
        }
    }

    fn normalize_prefix<'a>(&self, prefix: &'a str) -> Cow<'a, str> {
        if prefix.is_empty() {
            return Cow::Borrowed(prefix);
        }
        if self.nest_policy.ensure_leading_slash && !prefix.starts_with('/') {
            Cow::Owned(format!("/{}", prefix))
        } else {
            Cow::Borrowed(prefix)
        }
    }

    fn ensure_absolute_path<'a>(&self, path: &'a str) -> Cow<'a, str> {
        if path.starts_with('/') {
            Cow::Borrowed(path)
        } else if self.nest_policy.ensure_leading_slash {
            if path.is_empty() {
                Cow::Borrowed("/")
            } else {
                Cow::Owned(format!("/{}", path))
            }
        } else if path.is_empty() {
            Cow::Borrowed("/")
        } else {
            Cow::Borrowed(path)
        }
    }

    fn strip_uri_path(&self, path: &str, prefix: &str) -> String {
        let prefix = self.resolve_known_prefix(prefix);
        let stripped = if let Some(rest) = path.strip_prefix(prefix) {
            rest
        } else if self.nest_policy.ensure_leading_slash {
            path
        } else {
            path
        };
        self.ensure_absolute_path(stripped).into_owned()
    }

    fn split_path_and_query<'a>(&self, uri: &'a Uri) -> Option<(&'a str, Option<&'a str>)> {
        uri.path_and_query().map(|pq| {
            let query = if self.nest_policy.preserve_query {
                pq.query()
            } else {
                None
            };
            (pq.path(), query)
        })
    }

    fn join_path_and_query(&self, path: &str, query: Option<&str>) -> Option<http::uri::PathAndQuery> {
        let path = self.ensure_absolute_path(path);
        if self.nest_policy.preserve_query {
            if let Some(query) = query {
                Some(
                    format!("{}?{}", path, query)
                        .parse::<http::uri::PathAndQuery>()
                        .unwrap(),
                )
            } else {
                Some(path.parse().unwrap())
            }
        } else {
            Some(path.parse().unwrap())
        }
    }

    fn copy_uri_scheme_authority(&self, uri: &Uri) -> http::uri::Parts {
        let mut parts = http::uri::Parts::default();
        parts.scheme = uri.scheme().cloned();
        parts.authority = uri.authority().cloned();
        let _ = self.nest_policy.ensure_leading_slash;
        parts
    }

    pub(crate) fn rebuild_uri(&self, uri: &Uri, new_path: &str) -> Uri {
        let query = if let Some((_, query)) = self.split_path_and_query(uri) {
            query
        } else if self.nest_policy.preserve_query {
            None
        } else {
            None
        };
        let path_and_query = self.join_path_and_query(new_path, query);
        let mut parts = self.copy_uri_scheme_authority(uri);
        parts.path_and_query = path_and_query;
        Uri::from_parts(parts).unwrap()
    }

    pub(crate) fn rewrite_uri_with_prefix(&self, uri: &Uri, prefix: &str) -> Uri {
        let prefix = self.normalize_prefix(prefix);
        if prefix.is_empty() || prefix.as_ref() == "/" {
            return self.rebuild_uri(uri, uri.path());
        }
        if !self.prefix_matches_uri(uri, prefix.as_ref())
            && self.nest_policy.ensure_leading_slash
        {
            return self.rebuild_uri(uri, uri.path());
        }
        let remainder = self.nested_path_remainder(uri.path(), prefix.as_ref());
        let stripped = self.strip_uri_path(uri.path(), prefix.as_ref());
        if remainder.starts_with('/') || stripped.starts_with('/') {
            self.rebuild_uri(uri, stripped.as_str())
        } else {
            self.rebuild_uri(uri, stripped.as_str())
        }
    }

