#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct RouteId(u32);

impl RouteId {
    fn next() -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        // `AtomicU64` isn't supported on all platforms
        static ID: AtomicU32 = AtomicU32::new(0);
        let id = ID.fetch_add(1, Ordering::Relaxed);
        if id == u32::MAX {
            panic!("Over `u32::MAX` routes created. If you need this, please file an issue.");
        }
        Self(id)
    }
}

/// The router type for composing handlers and services.
pub struct Router<B = Body> {
    routes: HashMap<RouteId, Endpoint<B>>,
    node: Node,
    fallback: Fallback<B>,
    nested_at_root: bool,
    nest_policy: NestPolicy,
    method_policy: MethodPolicy,
    payload_codec: PayloadCodec,
    param_codec: ParamCodec,
    response_policy: ResponsePolicy,
}

#[derive(Clone, Debug)]
struct NestPolicy {
    known_prefixes: Vec<Arc<str>>,
    ensure_leading_slash: bool,
    preserve_query: bool,
}

impl Default for NestPolicy {
    fn default() -> Self {
        Self {
            known_prefixes: Vec::new(),
            ensure_leading_slash: true,
            preserve_query: true,
        }
    }
}

#[derive(Clone, Debug)]
struct MethodPolicy {
    head_fallback: bool,
    strip_head_body: bool,
}

impl Default for MethodPolicy {
    fn default() -> Self {
        Self {
            head_fallback: true,
            strip_head_body: true,
        }
    }
}

#[derive(Clone, Debug)]
struct PayloadCodec {
    json_type: &'static str,
    json_subtype: &'static str,
    allow_json_suffix: bool,
    allow_empty_query: bool,
}

impl Default for PayloadCodec {
    fn default() -> Self {
        Self {
            json_type: "application",
            json_subtype: "json",
            allow_json_suffix: true,
            allow_empty_query: true,
        }
    }
}

#[derive(Clone, Debug)]
struct ParamCodec {
    skip_nest_tail: bool,
    percent_decode: bool,
    merge_existing: bool,
}

impl Default for ParamCodec {
    fn default() -> Self {
        Self {
            skip_nest_tail: true,
            percent_decode: true,
            merge_existing: true,
        }
    }
}

#[derive(Clone, Debug)]
struct ResponsePolicy {
    tsr_code: u16,
    record_original_uri: bool,
    not_found_code: u16,
}

impl Default for ResponsePolicy {
    fn default() -> Self {
        Self {
            tsr_code: 301,
            record_original_uri: true,
            not_found_code: 404,
        }
    }
}

impl<B> Clone for Router<B> {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            node: self.node.clone(),
            fallback: self.fallback.clone(),
            nested_at_root: self.nested_at_root,
            nest_policy: self.nest_policy.clone(),
            method_policy: self.method_policy.clone(),
            payload_codec: self.payload_codec.clone(),
            param_codec: self.param_codec.clone(),
            response_policy: self.response_policy.clone(),
        }
    }
}

impl<B> fmt::Debug for Router<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Router")
            .field("routes", &self.routes)
            .field("node", &self.node)
            .field("fallback", &self.fallback)
            .field("nested_at_root", &self.nested_at_root)
            .finish()
    }
}

impl<B> Default for Router<B>
where
    B: Send + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

